package br.com.admeclesial.domain.financeiro;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="fornecedor",schema="adm_eclesial") public class Fornecedor { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,updatable=false) UUID uuid; @Enumerated(EnumType.STRING) @Column(name="tipo_pessoa",nullable=false,length=20) TipoPessoaFornecedor tipoPessoa; @Column(nullable=false,length=200) String nome; @Column(length=14) String cpfCnpj; @Column(length=200) String email; @Column(length=30) String telefone; @Column(nullable=false) boolean ativo; @PrePersist void pre(){if(uuid==null)uuid=UUID.randomUUID();} public Long getId(){return id;} public UUID getUuid(){return uuid;} public TipoPessoaFornecedor getTipoPessoa(){return tipoPessoa;} public String getNome(){return nome;} public String getCpfCnpj(){return cpfCnpj;} public String getEmail(){return email;} public String getTelefone(){return telefone;} public boolean getAtivo(){return ativo;} public void setTipoPessoa(TipoPessoaFornecedor v){tipoPessoa=v;} public void setNome(String v){nome=v;} public void setCpfCnpj(String v){cpfCnpj=v;} public void setEmail(String v){email=v;} public void setTelefone(String v){telefone=v;} public void setAtivo(boolean v){ativo=v;} }